     {"pages":table({"invoice_id":"VARCHAR","version":"INTEGER","page":"INTEGER","durable":"BOOLEAN","amount":"INTEGER"},[["I1",1,1,True,100],["I2",1,1,True,120],["I3",1,2,False,80],["I4",1,2,False,140],["I1",1,1,True,100]],"delivered invoice version",["invoice_id","version"])},
     "SELECT invoice_id AS entity_id, amount AS value FROM pages WHERE durable QUALIFY row_number() OVER(PARTITION BY invoice_id ORDER BY version DESC)=1",
     "SELECT invoice_id AS entity_id, amount AS value FROM pages QUALIFY row_number() OVER(PARTITION BY invoice_id ORDER BY version DESC)=1",
