CATALOG = {item["id"]: item for item in CASES}

def fault_layer(item):
    return 1 if item["number"] in (1,2) else 5 if item["number"]==10 else 3

def public_case(item, *, solutions=False):
    keys = ["id","number","title","sector","concept","priority","story","requirements","layers","limits","version"]
    result = {key: deepcopy(item[key]) for key in keys}
    result["fault_layer"] = fault_layer(item)
    if not solutions:
        faulty_models = [
            ("Repeated delivery join","Every delivered file contributes its matching sales, including repeated content."),
            ("Completed pages only","Only durable pages contribute invoices, although the stored checkpoint has moved past the missing page."),
            ("Arrival-order state","Delete events are filtered out; the last-arriving surviving update is treated as current."),
            ("Current-hour filter","Only events whose delivery hour equals the current processing hour enter the report."),
            ("Order-item detail join","Order totals are attached to each matching item without changing the child grain."),
            ("Gross revenue model","Payment amounts enter the revenue output; refunds are absent from the business calculation."),
            ("Permissive cast","Invalid text becomes zero; numeric values are treated as if they use the same unit."),
            ("All-day scan model","The scan-cost estimate includes every available daily partition."),
            ("Latest feature values","The most recently available stored feature is selected without a prediction-time boundary."),
            ("Newest candidate","Readers use the highest candidate version, regardless of its committed status."),
        ]
        result["layers"][1]=["Ingest","Current source intake","This boundary accepts delivered records and records progress. Receipt does not certify the transformed business result."]
        label,detail=faulty_models[item["number"]-1]
        result["layers"][3]=["Model",label,detail]
        result["layers"][4]=["Gate","Business contract","Compare declared keys, record coverage, and business meaning with the consumer's requirements."]
    for stage in ("predict","diagnose","fix","recall"):
        result[stage] = {key: deepcopy(item[stage][key]) for key in ("prompt","options")}
        Random(f"{VERSION}:{item['id']}:{stage}").shuffle(result[stage]["options"])
    if solutions:
        result.update({key:deepcopy(item[key]) for key in ("why","tradeoff","details","source_links")})
    return result
